#### Phase 1: Extension Registry Setup

**Duration**: 2 weeks
**Team**: Backend developers, database architects

**Step 1.1: Design Extension Registry Schema**

Create database schema to store tenant-extension mappings:

```sql
CREATE TABLE TenantExtensions (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    TenantId NVARCHAR(50) NOT NULL,
    ExtensionId NVARCHAR(100) NOT NULL,
    AssemblyName NVARCHAR(200) NOT NULL,
    TypeName NVARCHAR(500) NOT NULL,
    Version NVARCHAR(20) NOT NULL,
    IsEnabled BIT NOT NULL DEFAULT 1,
    LoadPriority INT NOT NULL DEFAULT 100,
    Configuration NVARCHAR(MAX), -- JSON configuration
    CreatedDate DATETIME2 NOT NULL DEFAULT GETUTCDATE(),
    ModifiedDate DATETIME2 NOT NULL DEFAULT GETUTCDATE(),
    CONSTRAINT UK_TenantExtension UNIQUE (TenantId, ExtensionId)
);

CREATE INDEX IX_TenantExtensions_TenantId ON TenantExtensions(TenantId)
    WHERE IsEnabled = 1;

CREATE TABLE ExtensionDependencies (
    Id UNIQUEIDENTIFIER PRIMARY KEY,
    ExtensionId NVARCHAR(100) NOT NULL,
    DependsOnExtensionId NVARCHAR(100) NOT NULL,
    MinVersion NVARCHAR(20),
    CONSTRAINT UK_ExtensionDependency UNIQUE (ExtensionId, DependsOnExtensionId)
);
```

**Step 1.2: Implement Registry Service**

Create service to query extension registry:

```csharp
public class TenantExtensionRegistry : ITenantExtensionRegistry
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IDistributedCache _cache;
    private readonly ILogger<TenantExtensionRegistry> _logger;

    public async Task<IReadOnlyList<ExtensionDescriptor>> GetExtensionsForTenantAsync(
        string tenantId, CancellationToken ct = default)
    {
        var cacheKey = $"extensions:tenant:{tenantId}";

        // Check distributed cache first
        var cached = await _cache.GetStringAsync(cacheKey, ct);
        if (cached != null)
        {
            return JsonSerializer.Deserialize<List<ExtensionDescriptor>>(cached);
        }

        // Query database
        var extensions = await _dbContext.TenantExtensions
            .Where(te => te.TenantId == tenantId && te.IsEnabled)
            .OrderBy(te => te.LoadPriority)
            .Select(te => new ExtensionDescriptor
            {
                Id = te.ExtensionId,
                AssemblyName = te.AssemblyName,
                TypeName = te.TypeName,
                Version = te.Version,
                Configuration = te.Configuration
            })
            .ToListAsync(ct);

        // Cache for 1 hour
        await _cache.SetStringAsync(cacheKey,
            JsonSerializer.Serialize(extensions),
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1) },
            ct);

        _logger.LogInformation("Loaded {Count} extensions for tenant {TenantId}",
            extensions.Count, tenantId);

        return extensions;
    }

    public async Task InvalidateCacheAsync(string tenantId)
    {
        await _cache.RemoveAsync($"extensions:tenant:{tenantId}");
    }
}
```

**Step 1.3: Configure Storage for Extension Assemblies**

Store extension assemblies in Azure Blob Storage:

```csharp
public class ExtensionStorageService
{
    private readonly BlobContainerClient _containerClient;

    public async Task<string> DownloadExtensionAsync(string assemblyName, string version)
    {
        var blobName = $"{assemblyName}/{version}/{assemblyName}.dll";
        var blobClient = _containerClient.GetBlobClient(blobName);

        var localPath = Path.Combine(Path.GetTempPath(), "extensions", assemblyName, version);
        Directory.CreateDirectory(localPath);

        var filePath = Path.Combine(localPath, $"{assemblyName}.dll");

        if (!File.Exists(filePath))
        {
            await blobClient.DownloadToAsync(filePath);
        }

        return filePath;
    }
}
```

**Step 1.4: Seed Initial Registry Data**

Populate registry with existing tenant extensions:

```csharp
public async Task SeedExtensionRegistryAsync()
{
    var tenantExtensions = new[]
    {
        new TenantExtension
        {
            TenantId = "fl-medicaid",
            ExtensionId = "fl-prior-auth-rules",
            AssemblyName = "Florida.PriorAuth.Extensions",
            TypeName = "Florida.PriorAuth.Extensions.PriorAuthRulesExtension",
            Version = "1.2.0",
            LoadPriority = 100
        },
        new TenantExtension
        {
            TenantId = "ca-medicaid",
            ExtensionId = "ca-claim-validation",
            AssemblyName = "California.Claims.Extensions",
            TypeName = "California.Claims.Extensions.ClaimValidationExtension",
            Version = "2.1.0",
            LoadPriority = 50
        }
    };

    await _dbContext.TenantExtensions.AddRangeAsync(tenantExtensions);
    await _dbContext.SaveChangesAsync();
}
```

