#### Phase 2: Tenant-Aware Loading Mechanism

**Duration**: 3 weeks
**Team**: Senior backend developers, DevOps

**Step 2.1: Implement AssemblyLoadContext Per Tenant**

Create isolated loading contexts:

```csharp
public class TenantAssemblyLoadContext : AssemblyLoadContext
{
    private readonly AssemblyDependencyResolver _resolver;
    private readonly ILogger _logger;

    public TenantAssemblyLoadContext(string name, string pluginPath, ILogger logger)
        : base(name, isCollectible: true)
    {
        _resolver = new AssemblyDependencyResolver(pluginPath);
        _logger = logger;
    }

    protected override Assembly? Load(AssemblyName assemblyName)
    {
        // Resolve dependencies using resolver
        var assemblyPath = _resolver.ResolveAssemblyToPath(assemblyName);
        if (assemblyPath != null)
        {
            _logger.LogDebug("Loading {Assembly} from {Path}",
                assemblyName.Name, assemblyPath);
            return LoadFromAssemblyPath(assemblyPath);
        }

        // Fall back to default context for framework assemblies
        return null;
    }

    protected override IntPtr LoadUnmanagedDll(string unmanagedDllName)
    {
        var libraryPath = _resolver.ResolveUnmanagedDllToPath(unmanagedDllName);
        if (libraryPath != null)
        {
            return LoadUnmanagedDllFromPath(libraryPath);
        }

        return IntPtr.Zero;
    }
}
```

**Step 2.2: Create Extension Loader Service**

```csharp
public class TenantExtensionLoader : ITenantExtensionLoader
{
    private readonly ConcurrentDictionary<string, TenantAssemblyLoadContext> _contexts = new();
    private readonly ConcurrentDictionary<string, WeakReference> _loadedAssemblies = new();
    private readonly IExtensionStorageService _storage;
    private readonly IServiceProvider _serviceProvider;
    private readonly ILogger<TenantExtensionLoader> _logger;

    public async Task<IExtension> LoadExtensionAsync(
        string tenantId,
        ExtensionDescriptor descriptor,
        CancellationToken ct = default)
    {
        var assemblyPath = await _storage.DownloadExtensionAsync(
            descriptor.AssemblyName,
            descriptor.Version);

        var context = _contexts.GetOrAdd(
            tenantId,
            tid =>
            {
                _logger.LogInformation(
                    "Creating new AssemblyLoadContext for tenant {TenantId}", tid);
                return new TenantAssemblyLoadContext(
                    $"Tenant-{tid}",
                    Path.GetDirectoryName(assemblyPath),
                    _logger);
            });

        var assembly = context.LoadFromAssemblyPath(assemblyPath);
        var type = assembly.GetType(descriptor.TypeName);

        if (type == null)
        {
            throw new InvalidOperationException(
                $"Type {descriptor.TypeName} not found in assembly {descriptor.AssemblyName}");
        }

        // Create instance with DI support
        var extension = (IExtension)ActivatorUtilities.CreateInstance(_serviceProvider, type);

        _logger.LogInformation(
            "Loaded extension {ExtensionId} for tenant {TenantId}",
            descriptor.Id, tenantId);

        return extension;
    }

    public async Task UnloadTenantExtensionsAsync(string tenantId)
    {
        if (_contexts.TryRemove(tenantId, out var context))
        {
            context.Unload();
            _logger.LogInformation(
                "Unloaded extensions for tenant {TenantId}", tenantId);

            // Force garbage collection to reclaim memory
            for (int i = 0; i < 3; i++)
            {
                GC.Collect();
                GC.WaitForPendingFinalizers();
            }
        }
    }
}
```

**Step 2.3: Integrate with Dependency Injection**

Register services in DI container:

```csharp
public static class ExtensionLoadingServiceCollectionExtensions
{
    public static IServiceCollection AddTenantExtensionLoading(
        this IServiceCollection services,
        Action<ExtensionLoadingOptions> configureOptions)
    {
        services.Configure(configureOptions);

        services.AddSingleton<ITenantExtensionRegistry, TenantExtensionRegistry>();
        services.AddSingleton<ITenantExtensionLoader, TenantExtensionLoader>();
        services.AddSingleton<IExtensionStorageService, ExtensionStorageService>();
        services.AddSingleton<IExtensionCache, ExtensionCache>();

        services.AddSingleton<IExtensionManager, ExtensionManager>();

        return services;
    }
}

// In Startup.cs
services.AddTenantExtensionLoading(options =>
{
    options.StorageConnectionString = configuration["ExtensionStorage:ConnectionString"];
    options.CacheExpiration = TimeSpan.FromMinutes(30);
    options.PreloadHighTrafficTenants = true;
});
```

**Step 2.4: Implement Extension Manager Facade**

High-level API for loading and accessing extensions:

```csharp
public class ExtensionManager : IExtensionManager
{
    private readonly ITenantExtensionRegistry _registry;
    private readonly ITenantExtensionLoader _loader;
    private readonly IExtensionCache _cache;
    private readonly ITenantContextAccessor _tenantContext;

    public async Task<IReadOnlyList<T>> GetExtensionsAsync<T>(
        string tenantId = null,
        CancellationToken ct = default) where T : IExtension
    {
        tenantId ??= _tenantContext.TenantId;

        if (string.IsNullOrEmpty(tenantId))
        {
            throw new InvalidOperationException("Tenant context not available");
        }

        var descriptors = await _registry.GetExtensionsForTenantAsync(tenantId, ct);
        var extensions = new List<T>();

        foreach (var descriptor in descriptors)
        {
            var extension = await _cache.GetOrLoadAsync(
                tenantId,
                descriptor.Id,
                async () => await _loader.LoadExtensionAsync(tenantId, descriptor, ct));

            if (extension is T typedExtension)
            {
                extensions.Add(typedExtension);
            }
        }

        return extensions;
    }
}
```

