#### Phase 3: Caching and Performance Optimization

**Duration**: 2 weeks
**Team**: Backend developers, performance engineers

**Step 3.1: Implement Multi-Tier Caching**

```csharp
public class ExtensionCache : IExtensionCache
{
    private readonly MemoryCache _memoryCache;
    private readonly IDistributedCache _distributedCache;
    private readonly ILogger<ExtensionCache> _logger;
    private readonly SemaphoreSlim _cacheLock = new(1, 1);

    public ExtensionCache(
        IOptions<MemoryCacheOptions> memoryCacheOptions,
        IDistributedCache distributedCache,
        ILogger<ExtensionCache> logger)
    {
        _memoryCache = new MemoryCache(memoryCacheOptions.Value);
        _distributedCache = distributedCache;
        _logger = logger;
    }

    public async Task<T> GetOrLoadAsync<T>(
        string tenantId,
        string extensionId,
        Func<Task<T>> loader) where T : IExtension
    {
        var key = $"{tenantId}:{extensionId}";

        // L1: Check memory cache
        if (_memoryCache.TryGetValue<T>(key, out var cached))
        {
            _logger.LogDebug("Extension {ExtensionId} found in L1 cache", extensionId);
            return cached;
        }

        // L2: Check distributed cache (for multi-instance deployments)
        var serialized = await _distributedCache.GetStringAsync(key);
        if (serialized != null)
        {
            _logger.LogDebug("Extension {ExtensionId} found in L2 cache", extensionId);
            var deserialized = JsonSerializer.Deserialize<T>(serialized);

            // Populate L1 cache
            _memoryCache.Set(key, deserialized, new MemoryCacheEntryOptions
            {
                SlidingExpiration = TimeSpan.FromMinutes(30),
                Size = 1
            });

            return deserialized;
        }

        // L3: Load from source with lock to prevent cache stampede
        await _cacheLock.WaitAsync();
        try
        {
            // Double-check after acquiring lock
            if (_memoryCache.TryGetValue<T>(key, out cached))
            {
                return cached;
            }

            _logger.LogInformation("Loading extension {ExtensionId} from source", extensionId);
            var extension = await loader();

            // Populate both caches
            _memoryCache.Set(key, extension, new MemoryCacheEntryOptions
            {
                SlidingExpiration = TimeSpan.FromMinutes(30),
                Size = 1
            });

            await _distributedCache.SetStringAsync(
                key,
                JsonSerializer.Serialize(extension),
                new DistributedCacheEntryOptions
                {
                    SlidingExpiration = TimeSpan.FromMinutes(60)
                });

            return extension;
        }
        finally
        {
            _cacheLock.Release();
        }
    }

    public async Task InvalidateAsync(string tenantId, string extensionId = null)
    {
        if (extensionId != null)
        {
            var key = $"{tenantId}:{extensionId}";
            _memoryCache.Remove(key);
            await _distributedCache.RemoveAsync(key);
        }
        else
        {
            // Invalidate all extensions for tenant
            // (requires tracking keys or using cache tags)
            _logger.LogInformation("Invalidating all extensions for tenant {TenantId}", tenantId);
        }
    }
}
```

**Step 3.2: Implement Preloading for High-Traffic Tenants**

```csharp
public class ExtensionPreloadService : BackgroundService
{
    private readonly IServiceProvider _serviceProvider;
    private readonly ILogger<ExtensionPreloadService> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        // Wait for application to fully start
        await Task.Delay(TimeSpan.FromSeconds(10), stoppingToken);

        using var scope = _serviceProvider.CreateScope();
        var extensionManager = scope.ServiceProvider.GetRequiredService<IExtensionManager>();
        var tenantService = scope.ServiceProvider.GetRequiredService<ITenantService>();

        var highTrafficTenants = await tenantService.GetHighTrafficTenantsAsync();

        _logger.LogInformation(
            "Preloading extensions for {Count} high-traffic tenants",
            highTrafficTenants.Count);

        await Parallel.ForEachAsync(
            highTrafficTenants,
            new ParallelOptions { MaxDegreeOfParallelism = 5, CancellationToken = stoppingToken },
            async (tenant, ct) =>
            {
                try
                {
                    var extensions = await extensionManager.GetExtensionsAsync<IExtension>(
                        tenant.Id, ct);
                    _logger.LogInformation(
                        "Preloaded {Count} extensions for tenant {TenantId}",
                        extensions.Count, tenant.Id);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex,
                        "Failed to preload extensions for tenant {TenantId}",
                        tenant.Id);
                }
            });
    }
}

// Register in Startup.cs
services.AddHostedService<ExtensionPreloadService>();
```

**Step 3.3: Implement Performance Monitoring**

```csharp
public class InstrumentedExtensionLoader : ITenantExtensionLoader
{
    private readonly ITenantExtensionLoader _inner;
    private readonly IMetricsCollector _metrics;
    private readonly ILogger _logger;

    public async Task<IExtension> LoadExtensionAsync(
        string tenantId,
        ExtensionDescriptor descriptor,
        CancellationToken ct = default)
    {
        var stopwatch = Stopwatch.StartNew();

        try
        {
            var extension = await _inner.LoadExtensionAsync(tenantId, descriptor, ct);

            stopwatch.Stop();
            _metrics.RecordExtensionLoadTime(
                tenantId,
                descriptor.Id,
                stopwatch.ElapsedMilliseconds);

            if (stopwatch.ElapsedMilliseconds > 500)
            {
                _logger.LogWarning(
                    "Slow extension load: {ExtensionId} for tenant {TenantId} took {Duration}ms",
                    descriptor.Id, tenantId, stopwatch.ElapsedMilliseconds);
            }

            return extension;
        }
        catch (Exception ex)
        {
            _metrics.RecordExtensionLoadFailure(tenantId, descriptor.Id);
            throw;
        }
    }
}
```

**Step 3.4: Implement Hot-Reload Support**

```csharp
public class ExtensionHotReloadService
{
    private readonly ITenantExtensionRegistry _registry;
    private readonly IExtensionCache _cache;
    private readonly ITenantExtensionLoader _loader;
    private readonly ILogger _logger;

    public async Task ReloadExtensionAsync(string tenantId, string extensionId)
    {
        _logger.LogInformation(
            "Hot-reloading extension {ExtensionId} for tenant {TenantId}",
            extensionId, tenantId);

        // Invalidate caches
        await _cache.InvalidateAsync(tenantId, extensionId);
        await _registry.InvalidateCacheAsync(tenantId);

        // Optionally unload old assembly (requires collectible context)
        await _loader.UnloadTenantExtensionsAsync(tenantId);

        _logger.LogInformation(
            "Extension {ExtensionId} reloaded for tenant {TenantId}",
            extensionId, tenantId);
    }

    public async Task HandleConfigurationChangeAsync(string tenantId)
    {
        _logger.LogInformation(
            "Extension configuration changed for tenant {TenantId}", tenantId);

        await _cache.InvalidateAsync(tenantId);
        await _registry.InvalidateCacheAsync(tenantId);
    }
}

// Subscribe to configuration change events
public class ExtensionConfigurationChangeHandler : INotificationHandler<ConfigurationChangedEvent>
{
    private readonly IExtensionHotReloadService _hotReload;

    public async Task Handle(ConfigurationChangedEvent notification, CancellationToken ct)
    {
        if (notification.ConfigurationType == "TenantExtension")
        {
            await _hotReload.HandleConfigurationChangeAsync(notification.TenantId);
        }
    }
}
```

