        ILogger<FloridaPriorAuthExtension> logger,
        IFloridaPriorAuthService priorAuthService)
    {
        _logger = logger;
        _priorAuthService = priorAuthService;
    }

    public Task InitializeAsync(IExtensionContext context)
    {
        _config = context.GetConfiguration<FloridaPriorAuthConfiguration>();
        _logger.LogInformation("Florida Prior Auth Extension initialized for tenant {TenantId}",
            context.TenantId);
        return Task.CompletedTask;
    }

    public async Task<ClaimProcessingResult> ProcessClaimAsync(
        Claim claim, CancellationToken ct)
    {
        // Florida-specific prior auth logic
        if (RequiresPriorAuth(claim))
        {
            var authStatus = await _priorAuthService.CheckPriorAuthAsync(
                claim.MemberId,
                claim.ServiceCode,
                ct);

            if (!authStatus.IsApproved)
            {
                return ClaimProcessingResult.Denied(
                    "Prior authorization required but not found");
            }
        }

        return ClaimProcessingResult.Approved();
    }

    public async Task<bool> ValidateClaimAsync(Claim claim, CancellationToken ct)
    {
        // Florida-specific validation rules
        return claim.ServiceState == "FL" &&
               await _priorAuthService.IsValidServiceCodeAsync(claim.ServiceCode, ct);
    }

    private bool RequiresPriorAuth(Claim claim)
    {
        return _config.ServiceCodesRequiringAuth.Contains(claim.ServiceCode);
    }
