#### Example 5: Usage in Application Code

```csharp
public class ClaimProcessingService
{
    private readonly IExtensionManager _extensionManager;
    private readonly ILogger<ClaimProcessingService> _logger;

    public async Task<ClaimProcessingResult> ProcessClaimAsync(
        Claim claim,
        CancellationToken ct)
    {
        // Get tenant-specific claim processing extensions
        var extensions = await _extensionManager
            .GetExtensionsAsync<IClaimProcessingExtension>(ct);

        _logger.LogInformation(
            "Processing claim {ClaimId} with {Count} extensions",
            claim.Id, extensions.Count);

        foreach (var extension in extensions)
        {
            try
            {
                // Validate with extension
                var isValid = await extension.ValidateClaimAsync(claim, ct);
                if (!isValid)
                {
                    _logger.LogWarning(
                        "Claim {ClaimId} failed validation by extension {ExtensionId}",
                        claim.Id, extension.Id);
                    return ClaimProcessingResult.Invalid(
                        $"Validation failed: {extension.Name}");
                }

                // Process with extension
                var result = await extension.ProcessClaimAsync(claim, ct);
                if (!result.IsApproved)
                {
                    _logger.LogInformation(
                        "Claim {ClaimId} denied by extension {ExtensionId}: {Reason}",
                        claim.Id, extension.Id, result.DenialReason);
                    return result;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Extension {ExtensionId} failed processing claim {ClaimId}",
                    extension.Id, claim.Id);

                // Continue with circuit breaker pattern
                if (ShouldFailOpen(extension))
                {
                    continue; // Skip failed extension
                }
                else
                {
                    throw; // Fail closed
                }
            }
        }

        return ClaimProcessingResult.Approved();
    }
}
