    "PreloadTenants": ["ca-medicaid"],
    "PreloadStrategy": "Startup"
  }
}
```

Implement startup preloading:

```csharp
public class ExtensionPreloadService : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken);

        // Preload California extensions
        var extensions = await _extensionManager
            .GetExtensionsAsync<IExtension>("ca-medicaid", stoppingToken);

        _logger.LogInformation(
            "Preloaded {Count} extensions for ca-medicaid",
            extensions.Count);
    }
}
```

**2. Aggressive Memory Caching**

Cache California extensions permanently:

```csharp
public async Task<T> GetOrLoadAsync<T>(string tenantId, string extensionId, Func<Task<T>> loader)
{
    var options = new MemoryCacheEntryOptions();

    if (_highTrafficTenants.Contains(tenantId))
    {
        // Never expire for high-traffic tenants
        options.Priority = CacheItemPriority.NeverRemove;
    }
    else
    {
        // Normal sliding expiration for other tenants
        options.SlidingExpiration = TimeSpan.FromMinutes(30);
    }

    return await _cache.GetOrLoadAsync(key, loader, options);
}
```

**3. Dedicated Resource Allocation**

Reserve memory for California extensions:

```yaml
