kind: Deployment
metadata:
  name: claims-processing
spec:
  replicas: 15
  template:
    spec:
      containers:
      - name: api
        resources:
          requests:
            memory: "2Gi"  # Baseline + California extensions
            cpu: "1000m"
          limits:
            memory: "4Gi"
            cpu: "2000m"
